import type { DetailRoute, DetailState } from "./entity-details";
import type { Entity } from "./search";
export type SearchResult =
  | { status: "idle" }
  | { status: "success"; term: string; entities: Entity[] }
  | { status: "error"; term: string; message: string };
export type PageModel =
  | { kind: "search"; query: string; strictness: number; result: SearchResult }
  | {
      kind: "detail";
      route: Exclude<DetailRoute, { kind: "search" }>;
      result: Exclude<DetailState, { kind: "loading" }>;
    };
<script lang="ts">
  import Icon from "./lib/Icon.svelte";
  import EntityIndicator from "./lib/EntityIndicator.svelte";
  import {
    entityHref,
    highlightName,
    readStrictness,
    searchConfiguration,
    type Entity,
  } from "./lib/search";

  import { onMount, untrack } from "svelte";
  import { page } from "$app/state";
  import { goto, afterNavigate } from "$app/navigation";
  import type { PageModel, SearchResult } from "./lib/page";
  let { model }: { model: Extract<PageModel, { kind: "search" }> } = $props();
  type SearchState = SearchResult | { status: "loading"; term: string };
  type SearchFocusShortcut =
    { modifier: "meta"; hint: "⌘ K" } | { modifier: "ctrl"; hint: "Ctrl K" };
  let searchFocusShortcut = $state<SearchFocusShortcut>({
    modifier: "ctrl",
    hint: "Ctrl K",
  });
  onMount(() => {
    if (/Mac/i.test(navigator.platform))
      searchFocusShortcut = { modifier: "meta", hint: "⌘ K" };
  });
  let query = $state(untrack(() => model.query));
  let strictness = $state(untrack(() => model.strictness));
  afterNavigate(({ type }) => {
    if (type === "popstate" || type === "link") {
      query = page.url.searchParams.get("q") ?? "";
      strictness = readStrictness(page.url.searchParams.get("strictness"));
    }
  });
  let composing = $state(false);
  let attempt = $state(0);
  let input: HTMLInputElement;
  let pending = $state(false);
  const term = $derived(query.trim());
  const charactersNeeded = $derived(
    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
  );
  const searchState = $derived<SearchState>(
    composing || charactersNeeded
      ? { status: "idle" }
      : pending ||
          model.query.trim() !== term ||
          model.strictness !== strictness
        ? { status: "loading", term }
        : model.result,
  );
  const announcement = $derived(
    searchState.status === "loading"
      ? "Searching…"
      : searchState.status === "success"
        ? `${searchState.entities.length} ${searchState.entities.length === 1 ? "result" : "results"} shown for ${searchState.term}.`
        : "",
  );

  $effect(() => {
    const currentTerm = term;
    const currentStrictness = strictness;
    const currentAttempt = attempt;
    if (
      composing ||
      [...currentTerm].length < searchConfiguration.minimumCharacters
    )
      return;
    if (
      !currentAttempt &&
      untrack(
        () =>
          model.query.trim() === currentTerm &&
          model.strictness === currentStrictness,
      )
    )
      return;
    let current = true;
    const timer = setTimeout(
      async () => {
        const url = new URL(window.location.href);
        url.searchParams.set("q", currentTerm);
        url.searchParams.set("strictness", String(currentStrictness));
        pending = true;
        try {
          await goto(url, { replace: true, reset: false, refreshAll: true });
        } finally {
          if (current) pending = false;
        }
      },
      currentAttempt ? 0 : searchConfiguration.debounceMs,
    );
    return () => {
      current = false;
      pending = false;
      clearTimeout(timer);
    };
  });

  function updateQuery(value: string) {
    attempt = 0;
    query = value;
    const url = new URL(window.location.href);
    if (value.trim()) url.searchParams.set("q", value.trim());
    else url.searchParams.delete("q");
    void goto(url, {
      shallow: true,
      replace: true,
      reset: false,
      state: page.state,
    });
  }

  function updateStrictness(value: string) {
    attempt = 0;
    strictness = readStrictness(value);
    const url = new URL(window.location.href);
    url.searchParams.set("strictness", String(strictness));
    void goto(url, {
      shallow: true,
      replace: true,
      reset: false,
      state: page.state,
    });
  }

  function clearSearch() {
    updateQuery("");
    input.focus();
  }

  function shortcut(event: KeyboardEvent) {
    if (
      event.key.toLowerCase() === "k" &&
      !event.defaultPrevented &&
      !event.isComposing &&
      !composing &&
      !event.shiftKey &&
      !event.altKey &&
      (searchFocusShortcut.modifier === "meta"
        ? event.metaKey && !event.ctrlKey
        : event.ctrlKey && !event.metaKey)
    ) {
      event.preventDefault();
      input.focus();
      return;
    }
    const target = event.target;
    const editing =
      target instanceof HTMLElement &&
      (target.isContentEditable ||
        ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));
    if (
      event.key === "/" &&
      !editing &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      event.preventDefault();
      input.focus();
    }
    if (event.key === "Escape" && target === input && !event.isComposing)
      clearSearch();
  }

  function atLimit(entities: Entity[]) {
    return ["MP", "Funder"].some(
      (kind) =>
        entities.filter((entity) => entity.kind === kind).length >=
        searchConfiguration.maxEntriesPerType,
    );
  }
</script>

<svelte:window onkeydown={shortcut} />

<main id="search">
  <div class="search-intro">
    <h1>Search MPs and funders</h1>
    <p>Find a name in the Register of Members’ Financial Interests.</p>
  </div>

  <form
    role="search"
    onsubmit={(event) => {
      event.preventDefault();
      if (!composing && !charactersNeeded) attempt += 1;
    }}
  >
    <label class="visually-hidden" for="entity-search"
      >Search MPs and funders</label
    >
    <div class="search-field">
      <span class="search-icon"><Icon name="search" size={24} /></span>
      <input
        id="entity-search"
        type="search"
        bind:this={input}
        value={query}
        oninput={(event) => updateQuery(event.currentTarget.value)}
        oncompositionstart={() => (composing = true)}
        oncompositionend={() => (composing = false)}
        placeholder="Enter an MP or funder’s name"
        autocomplete="off"
        spellcheck="false"
        aria-describedby="search-help"
      />
      {#if query}
        <button
          class="clear-button"
          type="button"
          aria-label="Clear search"
          onclick={clearSearch}><Icon name="close" size={18} /></button
        >
      {:else}
        <kbd class="search-shortcut" aria-hidden="true"
          >{searchFocusShortcut.hint}</kbd
        >
      {/if}
    </div>
    <p class="search-help" id="search-help">
      {#if term && charactersNeeded}
        Type {charactersNeeded} more {charactersNeeded === 1
          ? "character"
          : "characters"} to search.
      {:else if !term}
